samples := []int{120, 45, 300, 90, 210, 60, 150} // 一个采样窗口内的响应时间（毫秒）
sort.Slice(samples, func(i, j int) bool {
	return samples[i] < samples[j]
})
idx := (len(samples)*99+99)/100 - 1 // 第 99 百分位所在下标
if idx >= len(samples) {
	idx = len(samples) - 1
}
fmt.Println("P99 =", samples[idx], "ms")
